#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8
ENV_FILE="verification/india-run/deploy.env"
mkdir -p "$(dirname "$ENV_FILE")"
NEED_VM="true"

banner "TN EC: go live against the real TNREGINET portal"

# ── Stage 1: orientation + free reachability check ─────────────────────────
stage "Reachability check — is a VM even needed?"
say "The automation worker (service/src/providers/automation-worker.ts) is already"
say "built and proven against a stand-in portal. What's untested is the real"
say "tnreginet.gov.in, which is known to geo-block traffic from outside India."
say ""
say "Ground rules for everything that follows, so they're stated once up front:"
step "CAPTCHA and OTP are ALWAYS solved by a human (you) — never automated."
step "This wizard never asks for your TNREGINET password. That goes in your"
say "  own head / password manager only, never typed here or pasted to Claude."
say ""
say "First, the free check: is tnreginet.gov.in reachable from where YOU already"
say "are? If your own laptop's connection is India-based, you may not need a"
say "cloud VM at all — just run the service locally."
open_url "https://tnreginet.gov.in/portal/"
step "Did the portal actually load (not a timeout / refused-connection page)?"
if confirm "Portal loaded fine from my own connection?"; then
  NEED_VM="false"
  write_env "NEED_VM" "false"
  note "Good — skip the VM stage next. Run everything on this machine."
else
  NEED_VM="true"
  write_env "NEED_VM" "true"
  note "OK — the next stage provisions a small India-region VM."
fi

# ── Stage 2: provision an India-region VM (only if needed) ────────────────
stage "Provision an India-region VM"
if [[ "$NEED_VM" == "false" ]]; then
  say "Skipped — you already confirmed direct access in Stage 1."
else
  say "Pick ONE. This is a light workload (Playwright + one Chromium tab), so the"
  say "smallest 2GB instance is enough. Prices are approximate — check current"
  say "rates before buying, they change."
  say ""
  step "Vultr — Mumbai or Bengaluru region — 2GB Cloud Compute, ~\$12/mo, BILLED"
  say "  HOURLY — spin up, test, destroy, pay only for the hour. Best fit for a"
  say "  one-off test run."
  open_url "https://www.vultr.com/products/cloud-compute/"
  step "Linode (Akamai) — Chennai OR Mumbai region — Nanode/Shared 2GB, ~\$12/mo,"
  say "  also hourly billing. Chennai is a nice touch given the subject."
  open_url "https://www.linode.com/products/shared/"
  step "DigitalOcean — Bangalore (BLR1) — Basic Droplet 2GB, ~\$12/mo, daily-capped"
  say "  billing (cheaper to leave running for a multi-day test)."
  open_url "https://www.digitalocean.com/products/droplets"
  say ""
  say "Whichever you pick: sign up, add billing, and create ONE Ubuntu 22.04/24.04"
  say "instance in an India region with at least 2GB RAM. Add your SSH key during"
  say "creation — do not set a password login."
  pause "Instance created and you can SSH into it? Press Enter when ready."
  ask CLOUD_PROVIDER "Which provider did you use (vultr / linode / digitalocean / other):"
  ask VM_REGION "Which region (e.g. Mumbai, Chennai, Bangalore):"
  ask VM_IP "The instance's public IP address:"
  ask VM_SSH_USER "SSH login user (root, or ubuntu on some images):"
  write_env "CLOUD_PROVIDER" "$CLOUD_PROVIDER"
  write_env "VM_REGION" "$VM_REGION"
  write_env "VM_IP" "$VM_IP"
  write_env "VM_SSH_USER" "$VM_SSH_USER"
  note "Sanity check from here: ssh $VM_SSH_USER@$VM_IP"
fi

# ── Stage 3: prepare the runtime ───────────────────────────────────────────
stage "Install Node, the repo, and Playwright's Chromium"
if [[ "$NEED_VM" == "true" ]]; then
  say "Run these ON THE VM (ssh in first: ssh \$VM_SSH_USER@\$VM_IP)."
else
  say "Run these on THIS machine — you're already India-connected."
fi
say ""
step "Install Node 22+:"
note "  curl -fsSL https://deb.nodesource.com/setup_22.x | sudo bash -"
note "  sudo apt-get install -y nodejs git"
step "Get the project onto that machine — either:"
note "  git clone <your fork/remote>  (if you've pushed the repo somewhere), or"
note "  rsync -av --exclude node_modules \\"
note "    E:/PersonalProjects/tn-ec-feasibility/ \$VM_SSH_USER@\$VM_IP:~/tn-ec-feasibility/"
note "  (rsync runs from YOUR laptop, not the VM, if you go this route)"
step "Install dependencies and the real browser:"
note "  cd tn-ec-feasibility/service && npm install"
note "  npx playwright install chromium --with-deps"
pause "Repo present, npm install finished, Chromium installed? Press Enter."

# ── Stage 4: register a real TNREGINET account (fully manual) ─────────────
stage "Register a real TNREGINET account — you do this part alone"
warn "This step is 100% manual. Claude never creates accounts or handles"
warn "passwords — not a policy detail, a hard line."
say ""
say "From the India-connected machine's own browser (VM's desktop-forwarded"
say "browser, or your laptop if Stage 1 said you didn't need a VM):"
open_url "https://tnreginet.gov.in/portal/"
step "Click 'பயனர் பதிவு' / User Registration."
step "You'll need: an Indian mobile number you control (for OTP), an email,"
say "  and to pick a username + password + security question."
step "Complete the mobile OTP + email verification steps yourself."
step "Store the username/password in YOUR OWN password manager — not in this"
say "  repo, not in an .env file the wizard writes, not pasted back to Claude."
say ""
if confirm "Account registered and credentials safely stored by you?"; then
  write_env "TNREGINET_ACCOUNT_REGISTERED" "yes"
  note "Good. From here on, when the running service needs to log in, YOU type"
  note "the username/password into the actual portal fields yourself if asked,"
  note "or store them where only you can read them for the service's own config"
  note "(see Stage 6) — Claude still never sees the values."
else
  warn "Come back to this stage once the account exists — nothing after this"
  warn "point works without it."
fi

# ── Stage 5: capture the real portal's selectors ───────────────────────────
stage "Capture the live portal's real field selectors"
say "The worker currently ships with GUESSED selectors (written from public"
say "docs, since tnreginet.gov.in was unreachable from the dev sandbox). They"
say "almost certainly don't match the live DOM exactly. This stage collects the"
say "real ones."
say ""
step "Log in on the live portal, open DevTools (F12) → Elements."
step "Go to E-Services → Encumbrance Certificate → Search & View EC."
step "For each of: username / password / login CAPTCHA image / login submit /"
say "  zone, district, SRO, village dropdowns / survey + subdivision inputs /"
say "  date fields / search CAPTCHA / search submit / results table / OTP field"
say "  (if shown) — right-click → Inspect, and note its id or name attribute."
step "Write them into the checklist already in the repo:"
note "  poc/SELECTORS.md"
say ""
say "Once you have the real ids, send them to Claude (paste the filled-in"
say "checklist, or just the list of id=value pairs) and ask it to update"
say "service/src/providers/automation-worker.ts to match — that's a normal"
say "code edit, not something you need to do by hand."
pause "Selectors captured in poc/SELECTORS.md? Press Enter when done (or to skip for now)."

# ── Stage 6: configure the service for a live run ──────────────────────────
stage "Configure the service to point at the real portal"
say "On the India-connected machine, in service/.env (copy from .env.example"
say "if it doesn't exist yet), set:"
note "  AUTOMATION_PORTAL_URL=https://tnreginet.gov.in"
note "  AUTOMATION_USERNAME=<your TNREGINET username>"
note "  AUTOMATION_PASSWORD=<your TNREGINET password>"
note "  PROVIDER_ORDER=automation"
note "  HITL_MODE=console"
say ""
warn "That .env file lives ONLY on the India machine, is already in .gitignore,"
warn "and Claude does not read it. You are typing your own credentials into"
warn "your own config file — this is the one place they're allowed to live."
pause "service/.env updated on the India machine? Press Enter when ready."

# ── Stage 7: launch and run one real test search ───────────────────────────
stage "Launch the service and submit one real test search"
if [[ "$NEED_VM" == "true" ]]; then
  say "From YOUR laptop, tunnel the app port so you can use the browser UI"
  say "locally while it actually runs on the VM:"
  note "  ssh -L 8080:localhost:8080 \$VM_SSH_USER@\$VM_IP"
  say "Then, ON THE VM (in that same SSH session or another one):"
else
  say "On this machine:"
fi
note "  cd service && npm run dev"
step "Open the operator console: http://localhost:8080/public/console.html"
step "Open the manual test client in another tab: http://localhost:8080/demo"
step "Fill in ONE real, low-stakes property — ideally your own, or a survey"
say "  number you already know the public record for. Click Send."
step "Switch to the console tab as CAPTCHA / OTP tasks appear — read the"
say "  screenshot, type what you see, Submit. Repeat for each prompt."
step "Back in the demo tab, confirm a REAL result comes back (or a clear,"
say "  honest error — either is useful information at this point)."
say ""
if confirm "Got a live result (or a clear error) back from the real portal?"; then
  write_env "PORTAL_LIVE_VERIFIED" "yes"
  note "That's the milestone — first real, live, end-to-end EC pull."
else
  note "No shame in a first run failing on a selector mismatch — that's exactly"
  note "what Stage 5 exists to fix. Update the selector, restart, try again."
fi

# ── Stage 8: wrap up ────────────────────────────────────────────────────────
stage "Wrap up: save the work, control the spend"
say "Selector or config changes only exist on the India machine / your working"
say "copy right now. Bring them back:"
step "If you edited files directly on the VM: scp/rsync them back, or just"
say "  paste the diffs to Claude to apply here and commit."
step "If Claude already applied the selector edits here: git add + commit as"
say "  usual (npm test still all-green is worth confirming first)."
say ""
if [[ "$NEED_VM" == "true" ]]; then
  warn "The VM is billed while it exists. If you're done testing for now:"
  step "Vultr / Linode: destroy the instance from the dashboard (hourly billing"
  say "  means you've paid for what you used, not a monthly minimum)."
  step "DigitalOcean: destroy the Droplet, or at least power it off if you'll"
  say "  test again within a day or two."
  say ""
  say "Keep it running only while you're actively testing."
fi
note "Legal reminder, unchanged from before: TNREGINET's terms don't authorise"
note "automated access. This whole exercise is a conscious bet, not a solved"
note "problem — see research/vendor-mechanism-research.md and REPORT.md §3.3."

finish
